// decodedPreferTemplate routes a row's raw JSON through the rule's own exported decoder.
// prefer-template has no option surface (upstream's schema is []), so there is no decoder to
// route through and the harness is handed nil, which is what the config layer passes for a bare
// "error".
func decodedPreferTemplate(t *testing.T, raw string) any {
	t.Helper()
	if raw != "" {
		t.Fatalf("prefer-template takes no options, got %q", raw)
	}
	return nil
}

func TestPreferTemplateFires(t *testing.T) {
	t.Parallel()
	for _, testCase := range preferTemplateFiresCases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			result := rule_testing.RunWithOptions(t, PreferTemplate, preferTemplateFile, testCase.source,
				decodedPreferTemplate(t, testCase.options))
			rule_testing.ExpectFindings(t, result, testCase.ids...)
		})
	}
}

func TestPreferTemplateStaysSilent(t *testing.T) {
	t.Parallel()
	for _, testCase := range preferTemplateSilentCases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			result := rule_testing.RunWithOptions(t, PreferTemplate, preferTemplateFile, testCase.source,
				decodedPreferTemplate(t, testCase.options))
			rule_testing.ExpectClean(t, result)
		})
	}
}

// preferTemplateFixCase is one of upstream's `output` fixtures.
//
// `output` is the SPECIFICATION for the repair. This rule's repair is string surgery rather
// than a token swap -- escaping `${` and backticks by backslash parity, unescaping the
// original quote, carrying comments into curlies -- so a fixer that reports in the right
// place and writes the wrong bytes is indistinguishable at the message-id layer from a
// correct one. These 74 cases are the only thing that can tell them apart.
type preferTemplateFixCase struct {
	name   string
	source string
	wanted string
}

