// preferTemplateDeclineCases are the rows upstream reports on and deliberately does NOT repair.
//
// All five carry an octal or non-octal decimal escape. Those mean something different inside a
// template literal than inside a quoted string, so converting one changes what the program
// produces rather than how it is spelled. Reproducing the decline is part of the port.
var preferTemplateDeclineCases = []preferTemplateFixCase{
	{
		name:   "invalid-27",
		source: "foo + 'does not autofix octal escape sequence' + '\\033'",
	},
	{
		name:   "invalid-28",
		source: "foo + 'does not autofix non-octal decimal escape sequence' + '\\8'",
	},
	{
		name:   "invalid-29",
		source: "foo + '\\n other text \\033'",
	},
	{
		name:   "invalid-30",
		source: "foo + '\\0\\1'",
	},
	{
		name:   "invalid-31",
		source: "foo + '\\08'",
	},
}

func TestPreferTemplateRepairsWhatUpstreamRepairs(t *testing.T) {
	t.Parallel()
	for _, testCase := range preferTemplateRepairCases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			result := rule_testing.RunWithOptions(t, PreferTemplate, preferTemplateFile,
				testCase.source, decodedPreferTemplate(t, ""))
			rule_testing.ExpectFixedSource(t, result, testCase.wanted)
		})
	}
}

func TestPreferTemplateDeclinesTheRepairsUpstreamDeclines(t *testing.T) {
	t.Parallel()
	for _, testCase := range preferTemplateDeclineCases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			result := rule_testing.RunWithOptions(t, PreferTemplate, preferTemplateFile,
				testCase.source, decodedPreferTemplate(t, ""))
			if len(result.Diagnostics) == 0 {
				t.Fatalf("expected a finding; a decline withholds the FIX, not the report")
			}
			for _, diagnostic := range result.Diagnostics {
				if len(diagnostic.Fixes) != 0 {
					t.Errorf("proposed %d fix(es); upstream declines this case", len(diagnostic.Fixes))
				}
			}
		})
	}
}
